          "@type": "Question",
          "name": "What is Ascend WV?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ascend WV is a West Virginia University program that pays remote workers $12,000 in cash, over two years, to move to one of six parts of West Virginia. Applicants must show proof of employment and income before they are accepted."
          }
        },
        {
          "@type": "Question",
          "name": "How many people has Ascend WV brought to West Virginia?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "As of September 30, 2026, WVU reports 827 members and 1,641 new West Virginians, counting family members."
          }
        },
        {
          "@type": "Question",
          "name": "How much has Ohio committed to Intel?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ohio's package for Intel's planned chip plant was reported at about $2.1 billion when it was announced in 2022. Through June 2025, the state had paid at least $839.4 million of it, including $125.4 million from JobsOhio."
          }
        },
        {
          "@type": "Question",
          "name": "Why did West Virginia start gaining people from other states?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Most of the gain went to the Eastern Panhandle. IRS tax records show more people moving there from the Washington, D.C. area after COVID began. Ascend's members are too few to explain the change."
          }
        }
      ]
